import { signal } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { AppStateService } from '@shared/context/state/app-state.service';
import { HomeComponent } from './home.component';

describe('HomeComponent', () => {
  const create = (name?: string) => {
    TestBed.configureTestingModule({
      imports: [HomeComponent],
      providers: [{ provide: AppStateService, useValue: { user: () => signal({ authenticated: true, name }) } }],
    });
    TestBed.overrideComponent(HomeComponent, { set: { template: '', imports: [] } });
    return TestBed.createComponent(HomeComponent).componentInstance;
  };

  afterEach(() => TestBed.resetTestingModule());

  it('greets by the first name', () => {
    expect(create('  Ada  Lovelace ').name()).toBe('Ada');
  });

  it('has no name to greet when the user has none', () => {
    expect(create(undefined).name()).toBe('');
  });
});
